<script setup lang="ts">
import { onMounted, ref } from 'vue'
import * as api from '../../api/admin'
import type { Schema } from '../../types/api'
import AppDrawer from '../../components/AppDrawer.vue'
import AppDialog from '../../components/AppDialog.vue'
import ContentAccessPanel from './ContentAccessPanel.vue'
import { useAdminRequest, date, pretty, taskStates, settlements } from './shared'
const {busy,error,run}=useAdminRequest()
const tasks=ref<Schema<'TaskDiagnosticView'>[]>([]), cursor=ref<string|null>(null), state=ref(''), user=ref(''), stats=ref<Schema<'StatisticsView'>|null>(null)
const detail=ref<Schema<'TaskDiagnosticView'>|null>(null), detailOpen=ref(false), editOpen=ref(false), confirm=ref(false), mode=ref<'open'|'assign'|'resolve'>('open')
const investigation=ref<Schema<'InvestigationView'>|null>(null), owner=ref(''), policy=ref(''), evidence=ref(''), reason=ref(''), expected=ref(1)
const action=ref<Schema<'ResolveInvestigation'>['action']>('resume_original'), evidenceKind=ref<Schema<'Evidence'>['kind']>('review'), notice=ref('')
const investigations=ref<Schema<'InvestigationView'>[]>([]), investigationCursor=ref<string|null>(null)
let applied={state:'',user:''}
function load(reset=true){const filter=reset?{state:state.value,user:user.value}:applied;return run(()=>api.listTasks(reset?undefined:cursor.value??undefined,filter.state||undefined,filter.user||undefined),p=>{applied=filter;tasks.value=reset?p.items:[...tasks.value,...p.items];cursor.value=p.next_cursor})}
function loadStats(){return run(api.statistics,s=>{stats.value=s})}
function loadInvestigations(reset=true){return run(()=>api.listInvestigations(reset?undefined:investigationCursor.value??undefined),p=>{investigations.value=reset?p.items:[...investigations.value,...p.items];investigationCursor.value=p.next_cursor})}
function show(id:string){detail.value=null;investigation.value=null;detailOpen.value=true;return run(()=>api.diagnostics(id),d=>{detail.value=d})}
async function edit(kind:'open'|'assign'|'resolve') {
 if(!detail.value)return
 mode.value=kind;owner.value='';policy.value='';evidence.value='';reason.value='';expected.value=detail.value.state_version;error.value='';editOpen.value=true
 if(kind==='assign') await refreshInvestigation(true)
}
function refreshInvestigation(adopt=false){if(!detail.value)return;return run(()=>api.investigation(detail.value!.id),r=>{investigation.value=r;if(adopt){owner.value=r.owner??'';policy.value=r.policy_version;expected.value=r.version}})}
function refreshTask(){if(!detail.value)return;return run(()=>api.diagnostics(detail.value!.id),d=>{detail.value=d})}
function adoptVersion(){expected.value=mode.value==='assign'?investigation.value?.version??expected.value:detail.value?.state_version??expected.value}
async function save() {
 if(!detail.value)return
 const task=detail.value.id
 const call=():Promise<Schema<'InvestigationView'>|Schema<'ResolutionReceipt'>>=>mode.value==='open'?api.openInvestigation(task,{owner:owner.value,policy_version:policy.value,evidence:evidence.value}):mode.value==='assign'?api.assignInvestigation(task,{owner:owner.value,policy_version:policy.value,evidence:evidence.value,expected_version:expected.value,reason:reason.value}):api.resolveInvestigation(task,{action:action.value,policy_version:policy.value,evidence:{kind:evidenceKind.value,reference:evidence.value},expected_version:expected.value,reason:reason.value})
 if(await run(call,r=>{notice.value='处理已确认：'+('outcome' in r?r.outcome:r.status);confirm.value=false;editOpen.value=false}))await refreshTask()
}
onMounted(async()=>{await load();await loadStats()})
</script>
<template><div class="admin-page"><header class="page-heading"><h1>任务与用量</h1><p>先查原任务状态和结算，再依据证据处置异常。</p></header><p v-if="error" class="field-error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
<section class="panel"><div class="section-heading"><h2>用量统计</h2><button class="button" :disabled="busy" @click="loadStats">刷新统计</button></div><dl v-if="stats" class="admin-statistics"><dt>生成任务</dt><dd>{{ stats.generated_count }}</dd><dt>成功 / 终态任务</dt><dd>{{ stats.succeeded_count }} / {{ stats.terminal_count }}</dd><dt>成功率（成功 ÷ 全部终态）</dt><dd>{{ stats.success_rate===null?'暂无终态样本':(stats.success_rate*100).toFixed(1)+'%' }}</dd><dt>已消费积分</dt><dd>{{ stats.credits_consumed }}</dd><dt>注册赠送 / 管理员发放</dt><dd>{{ stats.signup_credits }} / {{ stats.admin_granted_credits }}</dd><dt>支付收入</dt><dd>未支持；赠送和发放不计收入</dd><dt>供应商实际成本 / 用量</dt><dd>不可获得（unavailable）</dd></dl></section>
<section class="panel"><h2>任务诊断</h2><form class="admin-filters" @submit.prevent="load()"><label>任务状态<select v-model="state"><option value="">全部</option><option v-for="(label,key) in taskStates" :key="key" :value="key">{{ label }}</option></select></label><label>用户标识<input v-model="user" placeholder="留空查询全部"></label><button class="button" :disabled="busy">查询任务</button></form><div class="admin-table"><table><thead><tr><th>任务 / 用户</th><th>状态</th><th>结算</th><th>耗时</th><th>诊断</th><th>操作</th></tr></thead><tbody><tr v-for="t in tasks" :key="t.id"><td>{{ t.id }}<small>{{ t.user_id }}</small></td><td>{{ taskStates[t.state] }}</td><td>{{ settlements[t.settlement_state] }}</td><td>{{ t.elapsed_seconds.toFixed(0) }} 秒</td><td>{{ t.diagnostic_code || '无异常代码' }}</td><td><button class="button" :disabled="busy" @click="show(t.id)">查看诊断</button></td></tr></tbody></table></div><p v-if="!busy && !tasks.length">暂无匹配任务。</p><button v-if="cursor" class="button" :disabled="busy" @click="load(false)">加载更多任务</button></section>
<section class="panel"><div class="section-heading"><h2>待核查记录</h2><button class="button" :disabled="busy" @click="loadInvestigations()">读取核查列表</button></div><ul class="admin-records"><li v-for="row in investigations" :key="row.task_id"><p>{{ row.task_id }} · {{ row.status }}</p><p>负责人 {{ row.owner || '未分配' }} · 截止 {{ date(row.deadline_at) }}</p><button class="button" :disabled="busy" @click="show(row.task_id)">核查原任务</button></li></ul><button v-if="investigationCursor" class="button" :disabled="busy" @click="loadInvestigations(false)">加载更多核查</button></section>
<ContentAccessPanel /></div>
<AppDrawer v-model:open="detailOpen" title="原任务诊断"><p v-if="error" class="field-error" role="alert">{{ error }}</p><template v-if="detail"><dl class="detail-list"><dt>任务标识</dt><dd>{{ detail.id }}</dd><dt>用户</dt><dd>{{ detail.user_id }}</dd><dt>状态 / 结算</dt><dd>{{ taskStates[detail.state] }} / {{ settlements[detail.settlement_state] }}</dd><dt>Agent 版本</dt><dd>{{ detail.agent_id }} / {{ detail.agent_version }}</dd><dt>诊断代码</dt><dd>{{ detail.diagnostic_code || '无异常代码' }}</dd><dt>核查</dt><dd>{{ detail.investigation_status || '尚未登记' }} / {{ detail.investigation_owner || '未分配' }}</dd><dt>创建时间</dt><dd>{{ date(detail.created_at) }}</dd></dl><p>常规诊断只显示状态。正文须通过下方独立内容授权入口读取。</p><div class="action-row"><button class="button" :disabled="busy" @click="refreshTask">刷新诊断</button><button class="button" :disabled="busy" @click="edit('open')">登记核查</button><button class="button" :disabled="busy" @click="edit('assign')">调整负责人</button><button class="button" :disabled="busy" @click="edit('resolve')">处置原任务</button></div><p v-if="notice" role="status">{{ notice }}</p></template></AppDrawer>
<AppDrawer v-model:open="editOpen" title="原任务核查与处置" purpose="edit"><form id="task-action" class="form-stack" @submit.prevent="confirm=true"><p>任务 {{ detail?.id }} · 草稿版本 {{ expected }}</p><label v-if="mode!=='resolve'">负责人用户标识<input v-model="owner" required data-initial-focus></label><label v-if="mode==='resolve'">处置动作<select v-model="action"><option value="resume_original">恢复原任务（不再次生成）</option><option value="confirm_failure">确认失败并释放冻结</option><option value="manual_close">人工关闭</option><option value="settle">依据完整交付结算</option></select></label><label>已确认 D-08 政策版本<input v-model="policy" required></label><label v-if="mode==='resolve'">证据类型<select v-model="evidenceKind"><option value="review">核查记录</option><option value="upstream_failure">上游确定失败</option><option value="durable_delivery">已持久保存完整成果</option></select></label><label>证据引用<input v-model="evidence" required pattern="[A-Za-z0-9_.:/-]{1,128}"></label><label v-if="mode!=='open'">操作原因<textarea v-model="reason" required maxlength="500" /></label><p>超时不证明失败。所有处置须通过服务端政策与证据校验。</p><p v-if="error" role="alert" class="field-error">{{ error }}</p><template v-if="mode!=='open'"><button class="button" type="button" :disabled="busy" @click="mode==='assign'?refreshInvestigation():refreshTask()">核对当前版本（保留草稿）</button><p>当前版本 {{ mode==='assign'?investigation?.version:detail?.state_version }}</p><button class="button" type="button" @click="adoptVersion">已核对，采用当前版本</button><details v-if="investigation"><summary>核查详情</summary><pre>{{ pretty(investigation) }}</pre></details></template></form><template #actions><button class="button primary" form="task-action" :disabled="busy">确认处置信息</button></template></AppDrawer>
<AppDialog v-model:open="confirm" title="确认原任务处置" purpose="delete"><p>本次处理任务 {{ detail?.id }}。</p><p>{{ mode==='resolve'?action:mode==='assign'?'调整负责人':'登记核查' }} · {{ reason || evidence }}</p><p>确认失败、关闭或结算会影响冻结积分，请核对证据与原任务。</p><p v-if="error" class="field-error" role="alert">{{ error }}</p><template #actions><button class="button danger" :disabled="busy" @click="save">提交原任务处理</button></template></AppDialog></template>
